// `@fx/contracts` — hand-written declaration copy of
// `fixtures/multi-repo/shared/contracts/src/index.ts`.
//
// The fixture must resolve without an install, so every repository that uses the
// shared package carries its own copy under `node_modules/@fx/contracts`. The
// copy in `gateway/` and the copy in `orders/` are BYTE-IDENTICAL on purpose:
// the linker merges a shared-package type by (package, name), and the two
// `structuralHash` values have to agree for `OrderDto` to come out as one
// `type:@fx/contracts#OrderDto` with every edge reference rewritten to it
// (P05 §9 D6, §12). Version skew between two copies is a different case — it
// keeps `meta.versions[]` and is left to a unit test.
//
// Change one copy and you must change the other, and `shared/contracts/src`
// with it:
//
//   diff fixtures/multi-repo/gateway/node_modules/@fx/contracts/index.d.ts \
//        fixtures/multi-repo/orders/node_modules/@fx/contracts/index.d.ts

/** The status of an order, as it goes over the wire. */
export type OrderStatus = 'created' | 'paid' | 'cancelled';

/** Nested on purpose, so the merged type has a field that is itself a type id. */
export interface Money {
  amount: number;
  currency: string;
}

/** The shape `orders` returns and `gateway` asks for. */
export interface OrderDto {
  id: string;
  customerId: string;
  status: OrderStatus;
  total: Money;
}

/** The body of `POST /orders`. */
export interface CreateOrderDto {
  customerId: string;
  total: Money;
}
